def parse_qsl_(qs):
    """
    Parse a query string into a list of (key, value) pairs.

    - Separates components by '&' only.
    - Each component is split on the first '='.
    - If no '=' is present, the value is an empty string.
    - Decodes percent-escapes and '+' as space in both keys and values.
    - Blank values are kept (i.e., 'a=' yields ('a', '')).
    """
    if not qs:
        return []

    def unquote(s):
        """Decode percent-escapes and '+' as space."""
        result = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '+':
                result.append(' ')
                i += 1
            elif c == '%':
                if i + 2 < n:
                    hex_chars = s[i+1:i+3]
                    try:
                        byte_val = int(hex_chars, 16)
                        result.append(chr(byte_val))
                        i += 3
                    except ValueError:
                        result.append(c)
                        i += 1
                else:
                    result.append(c)
                    i += 1
            else:
                result.append(c)
                i += 1
        return ''.join(result)

    pairs = []
    for component in qs.split('&'):
        if not component:
            continue
        if '=' in component:
            key, value = component.split('=', 1)
        else:
            key, value = component, ''
        pairs.append((unquote(key), unquote(value)))

    return pairs
